import{_ as t,a as o,b as r,c as i,d as s,e as a,f as n,g as l,h as c,i as d,j as p,k as u,l as h,m,n as b,o as f,p as g,q as k,r as y,s as w,t as v,u as S,v as C}from"./chunks/pic22.U07gr2Oy.js";import{_,o as x,c as P,ad as I}from"./chunks/framework.BJi0JF_z.js";const U=JSON.parse('{"title":"ZiZifn Worker Setup Guide","description":"Step-by-step tutorial for forking the project, obtaining Cloudflare credentials, and automated Worker deployment with GitHub Actions, finally generating VLESS proxy configs","frontmatter":{"layout":"doc","outline":"deep","lang":"en-US","title":"ZiZifn Worker Setup Guide","description":"Step-by-step tutorial for forking the project, obtaining Cloudflare credentials, and automated Worker deployment with GitHub Actions, finally generating VLESS proxy configs","date":"2026-08-08T00:00:00.000Z","editLink":true,"head":[["meta",{"name":"description","content":"Complete guide for deploying VLESS proxy based on WebAssembly and Rust on Cloudflare Workers using GitHub Actions"}],["meta",{"name":"keywords","content":"Serverless Runtime, cloudflare worker, vless proxy, github actions, rust wasm, zizifn, wrangler deploy"}]]},"headers":[],"relativePath":"en/topics/zizifn.md","filePath":"en/topics/zizifn.md"}'),A={name:"en/topics/zizifn.md"};function E(G,e,H,N,R,D){return x(),P("div",null,[...e[0]||(e[0]=[I('<h2 id="comprehensive-guide-to-setup-and-auto-deploy-vless-proxy-config" tabindex="-1">Comprehensive Guide to Setup and Auto-Deploy VLESS Proxy Config <a class="header-anchor" href="#comprehensive-guide-to-setup-and-auto-deploy-vless-proxy-config" aria-label="Permalink to &quot;Comprehensive Guide to Setup and Auto-Deploy VLESS Proxy Config&quot;">​</a></h2><p id="serverless-runtime"><strong>Step-by-step tutorial for forking, configuring security secrets, and running GitHub Actions</strong></p><br><p align="center"><img src="'+t+'" alt="ZiZifn Main Page"></p><br><br><p>The <strong>zizifn</strong> project is a secure proxy configuration based on the VLESS-WS-TLS/TCP protocol, developed with Rust and WebAssembly (Wasm) architecture, and deployed on Cloudflare Workers using the Wrangler tool. To implement this project on your personal account, follow the steps below carefully.</p><div class="info custom-block"><p class="custom-block-title"><code>Error 1101 and 1102</code></p><p>In this new structure, there is no need to add meaningless codes or heavy obfuscation!</p></div><br><h2>📚 Table of Contents</h2><nav class="table-of-contents"><ul><li><a href="#comprehensive-guide-to-setup-and-auto-deploy-vless-proxy-config">Comprehensive Guide to Setup and Auto-Deploy VLESS Proxy Config</a></li><li><a href="#fork">Step 1: Fork the Repository</a></li><li><a href="#token-time">Step 2: Obtain API Token from Cloudflare</a><ul><li><a href="#api-token">Create Token with Worker Edit Permissions</a></li></ul></li><li><a href="#enviroments">Step 3: Configure Secrets in GitHub</a></li><li><a href="#manual-deploy">Step 4: Enable and Run GitHub Action</a></li><li><a href="#how-to-use">How to Use</a><ul><li><a href="#access-the-admin-panel">Access the Admin Panel</a></li><li><a href="#get-subscription-link">Get Subscription Link</a></li></ul></li></ul></nav><br><h2 id="fork" tabindex="-1">Step 1: Fork the Repository <a class="header-anchor" href="#fork" aria-label="Permalink to &quot;Step 1: Fork the Repository {#fork}&quot;">​</a></h2><p>In the first step, you need to clone a copy of this project to your GitHub account.</p><ol><li><p>Go to the main repository page <a href="https://github.com/NiREvil/zizifn" target="_blank" rel="noreferrer">(Link)</a></p></li><li><p>Click the <strong>Fork</strong> icon (red arrow) at the top of the page.</p></li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+o+'" alt="How to fork the project on GitHub" width="1080px"></p></details><br><ol start="3"><li>On the next page, you can set a custom name for your fork; otherwise, click the <strong>Create fork</strong> button to transfer the project to your account.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+r+'" alt="How to fork the project on GitHub" width="1080px"></p></details><br><h2 id="token-time" tabindex="-1">Step 2: Obtain API Token from Cloudflare <a class="header-anchor" href="#token-time" aria-label="Permalink to &quot;Step 2: Obtain API Token from Cloudflare {#token-time}&quot;">​</a></h2><p>For automated deployment, GitHub Actions needs to connect to your Cloudflare account. We need two essential factors:</p><ul><li>CloudFlare Account ID</li><li>CloudFlare API Token</li></ul><div class="tip custom-block"><p class="custom-block-title"><strong>Note</strong></p><p>Previously, to get the Account ID, we had to go to the Workers &amp; Pages section and copy it from the bottom of the page. But now, when creating the token, the Account ID is also displayed, so we copy it from there.</p></div><br><h3 id="api-token" tabindex="-1">Create Token with Worker Edit Permissions <a class="header-anchor" href="#api-token" aria-label="Permalink to &quot;Create Token with Worker Edit Permissions {#api-token}&quot;">​</a></h3><ol><li>Log in to your Cloudflare dashboard.</li></ol><ul><li><a href="https://dash.cloudflare.com/login" target="_blank" rel="noreferrer">Login to Cloudflare Account</a></li><li><a href="https://dash.cloudflare.com/sign-up" target="_blank" rel="noreferrer">Create Cloudflare Account</a></li></ul><details class="details custom-block"><summary>Click to view.</summary><div class="tip custom-block"><p class="custom-block-title"><strong>Note</strong></p><p>Recently, Cloudflare doesn&#39;t allow creating accounts with fake emails. You can create one, but it won&#39;t be verified. Even if you try ten, thirty, or fifty times through the verification email they send, it will keep asking you to verify. So we recommend using G-Mail, Outlook, hotmail, protonmail, and similar reputable services to create a Cloudflare account.</p></div></details><br><ol start="2"><li>After logging into your Cloudflare account, open the left menu from the top of the page, type <strong>api</strong> in the <strong>Quick search</strong> box, and then select <strong>Account API Tokens</strong> from the search results.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+i+'" alt="Search for API token" width="1080px"></p><br><p align="center"><img src="'+s+'" alt="Select account API tokens" width="1080px"></p></details><br><ol start="3"><li>Click the <strong>Create Token</strong> button.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+a+'" alt="Click on Create token" width="1080px"></p></details><br><ol start="4"><li>Among the ready-made templates (red arrow), click on the <strong>Edit Cloudflare Workers</strong> option.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+n+'" alt="Change token template" width="1080px"></p><br><p align="center"><img src="'+l+'" alt="Select edit worker template" width="1080px"></p></details><br><ol start="5"><li>In the <strong>Token Expiration</strong> section, set a time frame for your token expiration according to your needs, then click on the view and create token option.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+c+'" alt="Token expiration time" width="1080px"></p></details><div class="tip custom-block"><p class="custom-block-title"><strong>Note</strong></p><p>Please note that after the token expires, your worker will not stop functioning. However, you will no longer be able to redeploy the project through GitHub. In that case, you will need to create a new token and replace the old one in your GitHub repository settings.</p></div><br><ol start="6"><li>On this page, copy the generated token (this token is displayed only once, so save it somewhere if needed). Also, the Account ID is displayed at the top of this page. Copy it as well since you&#39;ll need it. After confirming you&#39;ve copied both, click the <strong>confirm</strong> button to close the window.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+d+'" alt="Copy Cloudflare ID and token" width="1080px"></p></details><br><h2 id="enviroments" tabindex="-1">Step 3: Configure Secrets in GitHub <a class="header-anchor" href="#enviroments" aria-label="Permalink to &quot;Step 3: Configure Secrets in GitHub {#enviroments}&quot;">​</a></h2><p>Now we need to introduce the obtained information to your forked repository on GitHub so that the action can authenticate with your Cloudflare account.</p><ol><li>In your forked repository, go to the <strong>Settings</strong> tab.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+p+'" alt="Go to repo settings" width="1080px"></p></details><br><ol start="2"><li>From the menu, click on <strong>Secrets and variables</strong> and then select <strong>Actions</strong> from the submenu.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+u+'" alt="Select Actions" width="1080px"></p></details><br><ol start="3"><li>Click the <strong>New repository secret</strong> button and define the variables according to the table below:</li></ol><br><table tabindex="0"><thead><tr><th>Secret name</th><th style="text-align:center;">Status</th><th>Default value</th><th>Description</th></tr></thead><tbody><tr><td><code>CLOUDFLARE_API_TOKEN</code></td><td style="text-align:center;">✔️ Required</td><td>-</td><td>Your Cloudflare token with permission to edit workers.</td></tr><tr><td><code>CLOUDFLARE_ACCOUNT_ID</code></td><td style="text-align:center;">✔️ Required</td><td>-</td><td>Your Cloudflare account ID.</td></tr><tr><td><code>UUID</code></td><td style="text-align:center;">⚙️ Optional</td><td><code>be0ff9df-1468-41a0-8865-796d1c6800db</code></td><td>Your custom UUID (version 4).</td></tr><tr><td><code>PROXYIP</code></td><td style="text-align:center;">⚙️ Optional</td><td><code>di.nscl.ir</code></td><td>Proxy IP for routing traffic to services behind Cloudflare.</td></tr></tbody></table><br><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+h+'" alt="Create secret 1" width="1080px"></p><br><p align="center"><img src="'+m+'" alt="Create secret 2" width="1080px"></p><br><p align="center"><img src="'+b+'" alt="Final secret creation" width="1080px"></p></details><br><div class="danger custom-block"><p class="custom-block-title"><strong>Important Note</strong></p><p>Both of the first variables (Cloudflare ID and token) are required, meaning without obtaining and setting them in GitHub secrets, deploying the worker won&#39;t be possible. However, the next two variables, <code>UUID</code> and <code>PROXYIP</code>, are optional because default values are set in the code for both. However, it is highly recommended to copy a custom ID from <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">(this site)</a> and use it instead of the default ID. <br></p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+f+'" alt="Get UUID" width="1080px"></p><p>For other Proxy IPs, you can use this <a href="https://github.com/NiREvil/vless/blob/main/sub/ProxyIP.md" target="_blank" rel="noreferrer">Proxy Repository</a>.</p></details></div><br><h2 id="manual-deploy" tabindex="-1">Step 4: Enable and Run GitHub Action <a class="header-anchor" href="#manual-deploy" aria-label="Permalink to &quot;Step 4: Enable and Run GitHub Action {#manual-deploy}&quot;">​</a></h2><p>GitHub by default disables running actions on forked repositories. You need to enable it once and then run it.</p><ol><li><p>Go to the <strong>Actions</strong> tab at the top of your repository.</p></li><li><p>Click the green button</p></li></ol><p><strong>&quot;I understand my workflows, go ahead and enable them&quot;</strong></p><p>to allow actions to run.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+g+'" alt="Enable action" width="1080px"></p></details><br><ol start="3"><li>According to the screenshot below, first click on <strong>All workflows</strong> from the left side, then select the <strong>Deploy Worker</strong> workflow.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+k+'" alt="Select Deploy" width="1080px"></p></details><br><ol start="4"><li><p>On the right side of the page, a narrow bar with the <strong>Run workflow</strong> button will appear. Click on it.</p></li><li><p>In the pop-up form that opens, you can optionally set new <code>Proxy IP</code> or <code>UUID</code> values exceptionally for this specific run. (If left empty, the secrets or system defaults will be used. It&#39;s recommended to put both in the secrets.)</p></li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+y+'" alt="RUN" width="1080px"></p></details><br><ol start="6"><li>Finally, click the green <strong>Run workflow</strong> button inside the form.<br> After thirty to sixty seconds, a green checkmark will appear next to Deploy, indicating the process was successful.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+w+'" alt="Deploy-success" width="1080px"></p></details><br><div class="tip custom-block"><p class="custom-block-title">Important Note for One-Time Variables</p><p>Values entered in the <strong>Run workflow</strong> pop-up form are completely one-time use and won&#39;t be saved in the repository settings. This feature is useful for quickly testing different Proxy IPs or changing the UUID temporarily.</p></div><br><div class="info custom-block"><p class="custom-block-title"><strong>How It Works</strong></p><p>After clicking the <strong>Run workflow</strong> button, GitHub starts a cloud server, downloads and installs the Rust compiler (<code>cargo</code>) and <code>wasm-pack</code> tool, compiles the code, and then automatically creates a new Worker named <code>zr-wasm</code> in your Cloudflare account.</p><p>If you wish to change the Worker name, you can do so from the first line of the <a href="https://github.com/NiREvil/zizifn/blob/main/wrangler.toml" target="_blank" rel="noreferrer">wrangler.toml</a> file in the repository.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+v+'" alt="worker name" width="1080px"></p></details></div><br><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="access-the-admin-panel" tabindex="-1">Access the Admin Panel <a class="header-anchor" href="#access-the-admin-panel" aria-label="Permalink to &quot;Access the Admin Panel&quot;">​</a></h3><p>After deployment, simply add your UUID to the end of your Worker URL:</p><p><code>https://Your-Worker-URL/Your-UUID</code></p><p>For example:</p><p><code>https://0x00.workers.dev/be0ff9df-1468-41a0-8865-796d1c6800db</code></p><blockquote><p>If you haven&#39;t set the UUID variable and the code default is used, the value is:</p><div class="language-reg vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">reg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">be0ff9df</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1468</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">41a0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8865</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">796d1c6800db</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></blockquote><br><h3 id="get-subscription-link" tabindex="-1">Get Subscription Link <a class="header-anchor" href="#get-subscription-link" aria-label="Permalink to &quot;Get Subscription Link&quot;">​</a></h3><p>Your subscription link contains dozens of configs with clean Cloudflare IPs. Use the keys inside the panel to get it automatically.</p><p>Or if you need the subscription address manually to use in other clients, simply long-touch (press and hold) on one of the Import to ... buttons. The browser will then ask for permission to copy the link (only once, forever). After confirming the permission request by clicking Allow, the subscription link for that specific client will be copied for you.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+S+'" alt="Copy Subscription link" width="1080px"></p> <br><p>Sample subscription link:</p><p><a href="https://0x00.workers.dev/xray/be0ff9df-1468-41a0-8865-796d1c68000b" target="_blank" rel="noreferrer">https://0x00.workers.dev/xray/be0ff9df-1468-41a0-8865-796d1c68000b</a></p><p><a href="https://0x00.workers.dev/sb/be0ff9df-1468-41a0-8865-796d1c68000b" target="_blank" rel="noreferrer">https://0x00.workers.dev/sb/be0ff9df-1468-41a0-8865-796d1c68000b</a></p></details><br><div class="tip custom-block"><p class="custom-block-title">Difference between xray and sb</p><p>· xray path:</p><p>Suitable for clients that use the Xray core, such as: v2rayNG, MahsaNG, Hiddify, Nekoray, v2rayN, Streisand, Napsternet, NPVT, Happ, and etc.</p><br><p>· sb path:</p><p>Suitable for clients that use the SingBox core, such as: Nekobox, Exclave, Singbox, Husi, Karing, and etc.</p><br><p>· Clean Cloudflare IP</p><p>The IPs in the configs are sourced from the clean IP repository <a href="https://github.com/NiREvil/vless/blob/main/Cloudflare-IPs.json" target="_blank" rel="noreferrer">NiREvil/vless</a>. IP update cycle: every 4 hours.</p></div><br><div class="info custom-block"><p class="custom-block-title">Enhanced Configs</p><p>Recently, patterns have been suggested to address disruptions on Iran&#39;s internet and the upload speed weakness in configs built with Cloudflare Workers by adding two parameters to configs:</p><p>· Final Mask · Cypher suites</p><p>Additionally, to further optimize config performance, they have published a fork of v2rayNG called PattNG on GitHub. Therefore, alongside normal configs for v2rayNG, we will have another subscription called Enhanced, which will add configs with these new parameters pre-applied to your client. First, download and install the <a href="https://github.com/patterniha/v2rayNG/releases" target="_blank" rel="noreferrer">PattNG</a> client from the patterniha GitHub repository, then from your panel, click on Import to v2rayNG and select Enhanced.</p><p><a href="https://github.com/patterniha/v2rayNG/releases" target="_blank" rel="noreferrer">PattNG GitHub Link</a></p><br><p align="center"><img src="'+C+'" alt="PattNG" width="1920px"></p><br><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Deployment Engine</p><p>· GitHub Actions workflow runner (Ubuntu-24.04 VM) · Cloudflare Wrangler Action v3 · Many thanks to <a href="https://github.com/NiREvil" target="_blank" rel="noreferrer">NiREvil</a> and <a href="https://github.com/zizifn/edgetunnel" target="_blank" rel="noreferrer">zizifn</a></p></div></div><br><div class="danger custom-block"><p class="custom-block-title">Security Warning</p><details class="details custom-block"><summary>Click to view important security notes</summary><p>Never define sensitive Cloudflare tokens in manual input text fields!</p><p>Values entered manually in the form are stored in GitHub&#39;s log history and will be visible to everyone if your repository is public. Sensitive Cloudflare secrets must be registered through the path mentioned in Step 3 (Repository Secrets section) so that GitHub encrypts them.</p></details></div>',100)])])}const q=_(A,[["render",E]]);export{U as __pageData,q as default};
